steps.script:
var d = tree.root.get_node_or_null("/root/AbilityChoiceDialog")
if d != null and d.visible:
	d.get_ok_button().pressed.emit()
return "ok"

var m = tree.current_scene
var sc = m.shooting_controller
var scr = m.get_node("HUD_Right/VBoxContainer/ShootingScrollContainer")
var tr = sc.weapon_tree.get_global_rect()
var sr = scr.get_global_rect()
var visible = tr.position.y >= sr.position.y - 1.0 and tr.end.y <= sr.end.y + 1.0
return {"weapon_selected": sc.weapon_tree.get_selected() != null, "tree_fully_visible": visible}

var m = tree.current_scene
var scr = m.get_node("HUD_Right/VBoxContainer/ShootingScrollContainer")
var before = int(m.get_meta("deck_scroll_before", -1))
return {"scrolled_up": scr.scroll_vertical < before, "camera_untouched": m.view_offset == m.get_meta("deck_view_before", Vector2.INF)}

var labels: Array = []
var q: Array = [tree.root.get_node("/root/PadHintBar")]
while not q.is_empty():
	var n = q.pop_front()
	if n is Label:
		labels.append(str(n.text))
	for c in n.get_children():
		q.append(c)
return labels.has("Scroll Panel")
